fn logical_or(x1: Vec<bool>, x2: Vec<bool>) -> Vec<bool> {
    // The inputs must have the same length.
    assert_eq!(x1.len(), x2.len(), "Input vectors must be of the same length");
    // Zip the two vectors and compute the OR of each pair.
    x1.into_iter()
      .zip(x2.into_iter())
      .map(|(a, b)| a || b)
      .collect()
}

